/**
 * @brief Main window procedure that processes window messages
 *
 * Handles window messages including cleanup on window destruction and tracking
 * window activation state. When the window is destroyed, it releases all game
 * resources, terminates the timing thread, and exits the application.
 *
 * @param hWnd Window handle
 * @param Msg Message identifier
 * @param wParam Message parameter
 * @param lParam Message parameter
 * @return Result of message processing
 */
LRESULT __stdcall handleWindowMessages(HWND hWnd, UINT Msg, int wParam, LPARAM lParam)
{
  int i; // Counter for cleanup loop

  // Forward message to active game state handler if available
  if (g_gameActive && g_stateHandlers[(unsigned __int8)g_currentState])
    *(_DWORD *)(g_stateHandlers[(unsigned __int8)g_currentState] + 4) = Msg;

  // Handle window destruction
  if (Msg == WM_DESTROY)
  {
    // Mark game as inactive
    g_gameActive = 0;

    // Clean up all game state handlers
    for (i = 0; i < 9; ++i)
    {
      if (g_stateHandlers[i])
      {
        j__free((void *)g_stateHandlers[i]);
        g_stateHandlers[i] = 0;
      }
    }

    // Clean up game subsystems
    if (g_gameSystem)
      cleanupGameSystem((void *)g_gameSystem, 1);
    g_gameSystem = 0;

    // Clean up player objects
    if (g_player1)
      cleanupPlayerObject((unsigned __int16 *)g_player1, 1);
    if (g_player2)
      cleanupPlayerObject((unsigned __int16 *)g_player2, 1);

    // Release engine subsystems
    releaseSoundResources((int)&unk_7B0B60);
    releaseDirectInputDevices((_DWORD **)&unk_7B0968);
    releaseDirectDrawResources((_DWORD **)&g_graphicsSystem);

    // Terminate timing thread and clean up handles
    TerminateThread(hThread, 0);
    CloseHandle(hEvent);
    CloseHandle(hHandle);
    CloseHandle(hThread);

    // End timing period and exit application
    timeEndPeriod(1u);
    PostQuitMessage(1000);
  }
  else
  {
    // Handle window activation
    if (Msg == WM_ACTIVATEAPP)
      g_windowActive = wParam;
    else
      // Forward other messages to default handler
      return DefWindowProcA(hWnd, Msg, wParam, lParam);
  }

  return 0;
}// 790104: using guessed type int dword_790104;
