// Original name: sub_4054B0
int __thiscall openFileWithAccessMode(HANDLE *fileHandlePtr, LPCSTR fileName, char accessFlags)
{
  DWORD desiredAccess = 0;         // File access mode (read/write)
  DWORD creationDisposition = 0;    // How to open/create the file
  _SECURITY_ATTRIBUTES securityAttributes; // Security settings for the file

  // Clean up existing handle if any
  closeFileAndCleanupMemory(fileHandlePtr);
  
  // Parse access flags for read/write permissions
  if (accessFlags & 1)
    desiredAccess = 0x80000000;    // GENERIC_READ
  if (accessFlags & 2)
    desiredAccess |= 0x40000000u;  // GENERIC_WRITE
  
  // Parse creation disposition flags
  if (accessFlags & 0x10)
    creationDisposition = 5;        // CREATE_NEW
  if (accessFlags & 0x20)
    creationDisposition = 4;        // TRUNCATE_EXISTING
  if ((accessFlags & 0x10) && (accessFlags & 0x20))
    creationDisposition = 2;        // CREATE_ALWAYS
  if (!(accessFlags & 0x10) && !(accessFlags & 0x20))
    creationDisposition = 3;        // OPEN_EXISTING
  
  // Setup security attributes for handle inheritance
  securityAttributes.nLength = 12;
  securityAttributes.lpSecurityDescriptor = 0;
  securityAttributes.bInheritHandle = 1;
  
  // Open the file with specified parameters
  *fileHandlePtr = CreateFileA(
      fileName,
      desiredAccess,
      3u,                          // FILE_SHARE_READ | FILE_SHARE_WRITE
      &securityAttributes,
      creationDisposition,
      0x80u,                       // FILE_ATTRIBUTE_NORMAL
      0);                          // No template file
  
  // Check if file was opened successfully
  if (*fileHandlePtr != (HANDLE)-1)
    return 1;
  
  // Clear handle on failure
  *fileHandlePtr = 0;
  return 0;
}
//----- (004055A0) --------------------------------------------------------
// Original name: sub_4055A0
int __thiscall closeFileAndCleanupMemory(HANDLE *fileHandlePtr)
{
  // Close the file handle if valid
  if (*fileHandlePtr)
  {
    CloseHandle(*fileHandlePtr);
    *fileHandlePtr = 0;
  }
  
  // Free associated memory if allocated
  if (fileHandlePtr[1])
  {
    j__free(fileHandlePtr[1]);
    fileHandlePtr[1] = 0;
  }
  
  // Reset the rest of the structure
  resetFileHandleStruct(fileHandlePtr);
  return 1;
}

