/**
 * @brief Process player input and update control states with edge detection
 * 
 * @param inputManager Pointer to input management structure
 */
void __thiscall processPlayerInput(int *inputManager)
{
  int playerIndex;       // [esp+4h] [ebp-8h]
  _BYTE rawInputState[4]; // [esp+8h] [ebp-4h]

  // Process input for both players (0 and 1)
  for (playerIndex = 0; playerIndex < 2; ++playerIndex)
  {
    // Get raw input state from input device
    rawInputState[playerIndex] = pollPlayerInputState(inputManager[1], playerIndex);
    
    // Reset all input states for this player
    *((_BYTE *)inputManager + playerIndex + 12) = 0;  // Horizontal axis
    *((_BYTE *)inputManager + playerIndex + 14) = 0;  // Vertical axis
    *((_BYTE *)inputManager + playerIndex + 16) = 0;  // Button A state
    *((_BYTE *)inputManager + playerIndex + 18) = 0;  // Button B state
    *((_BYTE *)inputManager + playerIndex + 20) = 0;  // Button C state
    *((_BYTE *)inputManager + playerIndex + 22) = 0;  // Button D state
    
    // Process vertical movement (up/down)
    if ((rawInputState[playerIndex] & 8) != 0)  // Right
    {
      *((_BYTE *)inputManager + playerIndex + 14) = -1;  // Set horizontal to -1
    }
    else if ((rawInputState[playerIndex] & 4) != 0)  // Left
    {
      *((_BYTE *)inputManager + playerIndex + 14) = 1;   // Set horizontal to 1
    }
    
    // Process horizontal movement (left/right)
    if ((rawInputState[playerIndex] & 2) != 0)  // Down
    {
      *((_BYTE *)inputManager + playerIndex + 12) = -1;  // Set vertical to -1
    }
    else if ((rawInputState[playerIndex] & 1) != 0)  // Up
    {
      *((_BYTE *)inputManager + playerIndex + 12) = 1;   // Set vertical to 1
    }
    
    // Process Button A with edge detection
    if ((rawInputState[playerIndex] & 0x10) != 0)  // Button A pressed
    {
      // Set value to 1 only on first press (edge detection)
      *((_BYTE *)inputManager + playerIndex + 16) = inputManager[playerIndex + 6] == 0;
      inputManager[playerIndex + 6] = 1;  // Mark as held down
    }
    else
    {
      inputManager[playerIndex + 6] = 0;  // Mark as released
    }
    
    // Process Button B with edge detection
    if ((rawInputState[playerIndex] & 0x20) != 0)  // Button B pressed
    {
      *((_BYTE *)inputManager + playerIndex + 18) = inputManager[playerIndex + 8] == 0;
      inputManager[playerIndex + 8] = 1;
    }
    else
    {
      inputManager[playerIndex + 8] = 0;
    }
    
    // Process Button C with edge detection
    if ((rawInputState[playerIndex] & 0x40) != 0)  // Button C pressed
    {
      *((_BYTE *)inputManager + playerIndex + 20) = inputManager[playerIndex + 10] == 0;
      inputManager[playerIndex + 10] = 1;
    }
    else
    {
      inputManager[playerIndex + 10] = 0;
    }
    
    // Process Button D with edge detection
    if ((rawInputState[playerIndex] & 0x80) != 0)  // Button D pressed
    {
      *((_BYTE *)inputManager + playerIndex + 22) = inputManager[playerIndex + 12] == 0;
      inputManager[playerIndex + 12] = 1;
    }
    else
    {
      inputManager[playerIndex + 12] = 0;
    }
  }
}

