  *(double *)&entityCollection[56 * currentEntityIdx + 5392] = *(double *)(entityDataPtr + 8);
  *(double *)&entityCollection[56 * currentEntityIdx + 5396] = *(double *)(entityDataPtr + 16);
  
  // Various entity parameters
  LOBYTE(entityCollection[56 * currentEntityIdx + 5416]) = *(_BYTE *)(entityDataPtr + 24);  // Behavior flag
  *(_DWORD *)&entityCollection[56 * currentEntityIdx + 5418] = *(_DWORD *)(entityDataPtr + 28);  // Parameter 1
  LOBYTE(entityCollection[56 * currentEntityIdx + 5420]) = *(_BYTE *)(entityDataPtr + 32);  // Parameter 2
  LOBYTE(entityCollection[56 * currentEntityIdx + 5434]) = *(_BYTE *)(entityDataPtr + 44);  // Parameter 3
  *(_DWORD *)&entityCollection[56 * currentEntityIdx + 5422] = *(_DWORD *)(entityDataPtr + 36);  // Parameter 4
  HIBYTE(entityCollection[56 * currentEntityIdx + 5420]) = *(_BYTE *)(entityDataPtr + 33);  // Parameter 5
  
  // Advance to next entity slot
