//----- (00407D10) --------------------------------------------------------
// Original name: sub_407D10
void __thiscall updateScreenFadeEffect(_DWORD ***graphicsContext)
{
  // Check if we're in lighten mode (fade in)
  if (*((_BYTE *)graphicsContext + 82540) == 1)
  {
    // If the fade timer has expired
    if ((int)graphicsContext[20636] <= 0)
    {
      // If the delay timer has expired
      if ((int)graphicsContext[20634] <= 0)
      {
        // If brightness has reached minimum, end effect
        if (*((double *)graphicsContext + 10316) <= 0.0)
        {
          *((_BYTE *)graphicsContext + 82540) = 0; // Turn off effect
        }
        else
        {
          // Decrease brightness percentage
          *((double *)graphicsContext + 10316) = *((double *)graphicsContext + 10316) - 
                                               100.0 / (double)(int)graphicsContext[20637];
          
          // Clamp to minimum brightness
          if (*((double *)graphicsContext + 10316) <= 0.0)
            *((double *)graphicsContext + 10316) = 0.0;
            
          // Apply the updated palette effect
          createLightenedPalette(
            *graphicsContext, 
            (int)graphicsContext + 3893, 
            1u, 
            0xFFu, 
            100 - (unsigned __int64)*((double *)graphicsContext + 10316)
          );
        }
      }
      else
      {
        // Decrease delay timer
        graphicsContext[20634] = (_DWORD **)((char *)graphicsContext[20634] - 1);
      }
    }
    else
    {
      // Calculate brightness increase
      *((double *)graphicsContext + 10316) = (100.0 - *((double *)graphicsContext + 10316)) / 
                                           (double)(int)graphicsContext[20636] +
                                           *((double *)graphicsContext + 10316);
      
      // Clamp to maximum brightness
      if (*((double *)graphicsContext + 10316) > 100.0)
        *((double *)graphicsContext + 10316) = 100.0;
        
      // Apply the updated lighten effect if brightness is positive
      if (*((double *)graphicsContext + 10316) > 0.0)
        createLightenedPalette(
          *graphicsContext, 
          (int)graphicsContext + 3893, 
          1u, 
          0xFFu, 
          100 - (unsigned __int64)*((double *)graphicsContext + 10316)
        );
        
      // Decrease fade timer
      graphicsContext[20636] = (_DWORD **)((char *)graphicsContext[20636] - 1);
    }
  }
  // Check if we're in darken mode (fade out)
  else if (*((char *)graphicsContext + 82540) == -1)
  {
    // If the fade timer has expired
    if ((int)graphicsContext[20636] <= 0)
    {
      // If the delay timer has expired
      if ((int)graphicsContext[20634] <= 0)
      {
        // If brightness has reached minimum, end effect
        if (*((double *)graphicsContext + 10316) >= 0.0)
        {
          *((_BYTE *)graphicsContext + 82540) = 0; // Turn off effect
        }
        else
        {
          // Increase brightness percentage (moving toward zero from negative)
          *((double *)graphicsContext + 10316) = 100.0 / (double)(int)graphicsContext[20637] + 
                                               *((double *)graphicsContext + 10316);
          
          // Clamp to minimum brightness
          if (*((double *)graphicsContext + 10316) >= 0.0)
            *((double *)graphicsContext + 10316) = 0.0;
            
          // Apply the updated darken effect
          createDarkenedPalette(
            *graphicsContext, 
            (int)graphicsContext + 3893, 
            1u, 
            0xFFu, 
            (unsigned __int64)*((double *)graphicsContext + 10316) + 100
          );
        }
      }
      else
      {
        // Decrease delay timer
        graphicsContext[20634] = (_DWORD **)((char *)graphicsContext[20634] - 1);
      }
    }
    else
    {
      // Calculate brightness decrease
      *((double *)graphicsContext + 10316) = *((double *)graphicsContext + 10316) -
                                           (*((double *)graphicsContext + 10316) + 100.0) / 
                                           (double)(int)graphicsContext[20636];
      
      // Clamp to minimum brightness
      if (*((double *)graphicsContext + 10316) < -100.0)
        *((double *)graphicsContext + 10316) = -100.0;
        
      // Apply the updated darken effect if brightness is negative
      if (*((double *)graphicsContext + 10316) < 0.0)
        createDarkenedPalette(
          *graphicsContext, 
          (int)graphicsContext + 3893, 
          1u, 
          0xFFu, 
          (unsigned __int64)*((double *)graphicsContext + 10316) + 100
        );
        
      // Decrease fade timer
      graphicsContext[20636] = (_DWORD **)((char *)graphicsContext[20636] - 1);
    }
  }
}

