  // Width at bytes 18-19, height at bytes 22-23
  imageWidth = (*((unsigned __int8 *)fileData + 19) << 8) + *((unsigned __int8 *)fileData + 18);
  
  // Align width to 4-byte boundary if needed
  imageWidth += (imageWidth % 4 > 0) * (4 - imageWidth % 4);
  
