  // Setup DirectDraw surface descriptor
  surfaceDesc[0] = 108;         // sizeof(DDSURFACEDESC)
  surfaceDesc[1] = 7;           // DDSD_CAPS | DDSD_HEIGHT | DDSD_WIDTH
  surfaceDesc[26] = 2112;       // Surface capabilities
  surfaceDesc[3] = imageWidth;  // Width
  surfaceDesc[2] = imageHeight; // Height
  
