//----- (00409740) --------------------------------------------------------
// Original name: sub_409740
int __thiscall loadExtendedImageToSurface(_DWORD **graphicsContext, _DWORD *destSurface, 
                                        unsigned __int8 *sourceData, 
                                        unsigned __int8 rleThreshold, char colorOffset)
{
  int columnIndex;                 // Loop counter for width
  int rowIndex;                    // Loop counter for height
  int directColumnIndex;           // For direct copy column loop
  int directRowIndex;              // For direct copy row loop
  _DWORD surfaceDescriptor[29];    // DirectDraw surface descriptor
  char rleCounter;                 // Run-length counter
  char pixelValue;                 // Current pixel value
  int result;                      // API call results
  int imageWidth;                  // Width of the image
  int imageHeight;                 // Height of the image
  int sourceOffset;                // Current offset in source data
  int targetBufferPtr;             // Pointer to pixel data in surface
  unsigned __int8 pixelByte;       // Temporary pixel value
  int v19[4];                      // Surface lock info
  int surfacePitch;                // Surface pitch (bytes per row)
  int surfaceDataPtr;              // Surface data pointer from lock

  // Initialize variables
  sourceOffset = 0;
  rleCounter = 0;
  pixelValue = 0;
  
  // Extract image dimensions from first 4 bytes of source (little endian)
  imageWidth = (sourceData[1] << 8) + *sourceData;
  imageHeight = (sourceData[3] << 8) + sourceData[2];
  sourceOffset = 4;
  
  // Setup DirectDraw surface descriptor
  surfaceDescriptor[0] = 108;          // sizeof(DDSURFACEDESC)
  surfaceDescriptor[1] = 7;            // DDSD_CAPS | DDSD_HEIGHT | DDSD_WIDTH
  surfaceDescriptor[26] = 2112;        // Surface capability flags
  surfaceDescriptor[3] = imageWidth;   // Surface width
  surfaceDescriptor[2] = imageHeight;  // Surface height
  
  // Create DirectDraw surface
  result = (*(int (__stdcall **)(_DWORD *, _DWORD *, _DWORD *, _DWORD))(*graphicsContext[33282] + 24))
              (graphicsContext[33282], surfaceDescriptor, destSurface, 0);
              
  if (result)
  {
    MessageBoxA(0, &byte_78784C, 0, 0);  // "Failed to create surface"
    return 0;
  }
  
  // Lock surface to get direct access to pixel data
  v19[0] = 108;  // sizeof(DDSURFACEDESC)
  result = (*(int (__stdcall **)(_DWORD, _DWORD, int *, int, _DWORD))(*(_DWORD *)*destSurface + 100))
              (*destSurface, 0, v19, 1, 0);
              
  targetBufferPtr = surfaceDataPtr;  // Surface memory
  
  // Process image data based on RLE threshold
  if (rleThreshold)
  {
    // Using RLE compression mode
    for (rowIndex = 0; rowIndex < imageHeight; ++rowIndex)
    {
      for (columnIndex = 0; columnIndex < imageWidth; ++columnIndex)
      {
        if (rleCounter)
        {
          // Still processing run of same pixel
          --rleCounter;
        }
        else if (sourceData[sourceOffset] > (int)rleThreshold)
        {
          // Run of same pixel: Get count and skip
          rleCounter = sourceData[sourceOffset++] - rleThreshold - 1;
        }
        else
        {
          // Process normal pixel with color mapping
          if (sourceData[sourceOffset] < 0x28u)  // Special handling based on value
            pixelValue = colorOffset + sourceData[sourceOffset];
          else
            pixelValue = sourceData[sourceOffset] - 121;
          ++sourceOffset;
        }
        // Write pixel to surface
        *(_BYTE *)(targetBufferPtr + columnIndex + surfacePitch * rowIndex) = pixelValue;
      }
    }
  }
  else
  {
    // Direct copy mode (no compression)
    for (directRowIndex = 0; directRowIndex < imageHeight; ++directRowIndex)
    {
      for (directColumnIndex = 0; directColumnIndex < imageWidth; ++directColumnIndex)
      {
        // Get pixel value
        pixelByte = sourceData[directColumnIndex + 4 + imageWidth * directRowIndex];
        
        // Apply special color mapping and flip vertically (surface origin is top-left)
        if (pixelByte < 0x28u)
          *(_BYTE *)(targetBufferPtr + directColumnIndex + surfacePitch * (imageHeight - 1 - directRowIndex)) = 
              colorOffset + pixelByte;
        else
          *(_BYTE *)(targetBufferPtr + directColumnIndex + surfacePitch * (imageHeight - 1 - directRowIndex)) = 
              pixelByte - 121;
              
        ++sourceOffset;
      }
    }
  }
  
  // Unlock surface
  (*(void (__stdcall **)(_DWORD, int))(*(_DWORD *)*destSurface + 128))(*destSurface, surfaceDataPtr);
  
  // Return number of bytes processed
  return sourceOffset;
}

//----- (00409A90) --------------------------------------------------------// Original name: sub_409A90
BOOL __thiscall blitSurfaceWithTransparency(_DWORD **graphicsContext,
        int destX, int destY, int destRight, int destBottom, 
        int sourceSurface, int sourceX, int sourceY, int sourceRight, int sourceBottom,
        char transparentColor, int flipHorizontal)
{
  int destPtr;               // Destination memory pointer
  int sourcePtr;             // Source memory pointer
  int row;                   // Row loop counter
  int col;                   // Column loop counter
  char pixelColor;           // Current pixel color
  int destRow;               // For normal blit loop
  int sourceRow;             // For normal blit loop
  int normalRow;             // For normal blit
  int normalCol;             // For normal blit
  int flipRow;               // For flipped blit
  int flipCol;               // For flipped blit
  char skipColor;            // Transparent color to skip
  int originalSourceY;       // Keep original source Y for flip calculations
  int result;                // API call results
  int lockResult;            // Lock result
  int flipSourceY;           // Adjusted source Y for flip
  int width;                 // Width of the copy region
  int height;                // Height of the copy region
  int destSurfaceInfo[4];    // Destination surface lock info
  int destPitch;             // Destination surface pitch
  int destData;              // Destination surface data pointer
  int sourceSurfaceInfo[4];  // Source surface lock info
  int sourcePitch;           // Source surface pitch
  int sourceData;            // Source surface data pointer
  
  // Store original source Y coordinate
  originalSourceY = sourceY;
  
  // Validate rectangle bounds
  if (destY >= destBottom || destX >= destRight)
    return 1;
  if (sourceY >= sourceBottom || sourceX >= sourceRight)
    return 1;
    
  // Clip the source and destination rectangles to valid boundaries
  if (destY < 0)
  {
    sourceY -= destY;
    destY = 0;
  }
  if (destX < 0)
  {
    sourceX -= destX;
    destX = 0;
  }
  if (destBottom > 240)  // Screen height limit
  {
    sourceBottom -= destBottom - 240;
    destBottom = 240;
  }
  if (destRight > 320)  // Screen width limit
  {
    sourceRight -= destRight - 320;
    destRight = 320;
  }
  
  // Adjust coordinates for horizontal flipping if needed
  if (flipHorizontal)
  {
    flipSourceY = originalSourceY - sourceX;
    sourceX = originalSourceY - sourceRight;
    sourceRight = flipSourceY;
  }
  
  // Double-check bounds after clipping
  if (destY >= destBottom || destX >= destRight)
    return 1;
  if (sourceY >= sourceBottom || sourceX >= sourceRight)
    return 1;
  
  // Lock the source surface
  sourceSurfaceInfo[0] = 108;  // sizeof(DDSURFACEDESC)
  result = (*(int (__stdcall **)(int, int *, int *, int, _DWORD))(*(_DWORD *)sourceSurface + 100))
              (sourceSurface, &sourceX, sourceSurfaceInfo, 17, 0);
  if (result)
    return result != -2005532222;  // DDERR_WASSTILLDRAWING
    
  // Lock the destination surface
  destSurfaceInfo[0] = 108;  // sizeof(DDSURFACEDESC)
  lockResult = (*(int (__stdcall **)(_DWORD *, int *, int *, int, _DWORD))(*graphicsContext[33284] + 100))
                (graphicsContext[33284], &destX, destSurfaceInfo, 1, 0);
  if (lockResult)
    return lockResult != -2005532222;  // DDERR_WASSTILLDRAWING
    
  // Calculate dimensions of the region to copy
  width = destRight - destX;
  height = destBottom - destY;
  
  // Copy pixels with transparency handling
  if (transparentColor)
  {
    skipColor = transparentColor;
    
    if (flipHorizontal)
    {
      // Flipped copy with transparency
      destPtr = destData;
      sourcePtr = sourceData;
      row = height - 1;
      do
      {
        col = width - 1;
        do
        {
          pixelColor = *(_BYTE *)(sourcePtr + width - 1 - col);
          if (skipColor != pixelColor)
            *(_BYTE *)(destPtr + col) = pixelColor;
          --col;
        }
        while (col >= 0);
        sourcePtr += sourcePitch;
        destPtr += destPitch;
        --row;
      }
      while (row >= 0);
    }
    else
    {
      // Normal copy with transparency
      destRow = destData;
      sourceRow = sourceData;
      normalRow = height - 1;
      do
      {
        normalCol = width - 1;
        do
        {
          pixelColor = *(_BYTE *)(sourceRow + normalCol);
          if (skipColor != pixelColor)
            *(_BYTE *)(destRow + normalCol) = pixelColor;
          --normalCol;
        }
        while (normalCol >= 0);
        sourceRow += sourcePitch;
        destRow += destPitch;
        --normalRow;
      }
      while (normalRow >= 0);
    }
  }
  else
  {
    // Direct copy without transparency
    flipRow = destData;
    flipCol = sourceData;
    row = height - 1;
    do
    {
      col = width - 1;
      do
      {
        *(_BYTE *)(flipRow + col) = *(_BYTE *)(flipCol + col);
        --col;
      }
      while (col >= 0);
      flipCol += sourcePitch;
      flipRow += destPitch;
      --row;
    }
    while (row >= 0);
  }
  
  // Unlock surfaces
  (*(void (__stdcall **)(_DWORD *, int))(*graphicsContext[33284] + 128))(graphicsContext[33284], destData);
  (*(void (__stdcall **)(int, int))(*(_DWORD *)sourceSurface + 128))(sourceSurface, sourceData);
  
  return 1;
}

