//----- (0040AAE0) --------------------------------------------------------// Original name: sub_40AAE0
BOOL __thiscall blitShadowEffect(
        _DWORD **graphicsContext,
        int destX, int destY, int destRight, int destBottom, 
        int sourceSurface, int sourceX, int sourceY, int sourceRight, int sourceBottom,
        char transparentColor, int flipHorizontal)
{
  int destPtr;                 // Destination memory pointer
  int sourcePtr;               // Source memory pointer 
  int row;                     // Row loop counter
  int col;                     // Column loop counter
  int normalDestPtr;           // For normal blit
  int normalSourcePtr;         // For normal blit
  int normalRow;               // For normal blit row
  int normalCol;               // For normal blit col
  int directDestPtr;           // For direct blit
  int directSourcePtr;         // For direct blit
  int directRow;               // For direct blit row
  int directCol;               // For direct blit col
  char skipColor;              // Transparency color key
  int originalSourceY;         // Original sourceY for flip calculations
  int lockResult;              // API lock results
  int flipResult;              // API lock results for flip
  int flipSourceY;             // Adjusted source Y for flip
  int width;                   // Width of region to copy
  int height;                  // Height of region to copy
  int destSurfaceInfo[4];      // Destination surface lock info
  int destPitch;               // Destination surface pitch
  int destData;                // Destination surface data pointer
  int sourceSurfaceInfo[4];    // Source surface lock info
  int sourcePitch;             // Source surface pitch
  int sourceData;              // Source surface data pointer

  originalSourceY = sourceY;
  
  // Validate rectangle bounds
  if (destY >= destBottom || destX >= destRight)
    return 1;
  if (sourceY >= sourceBottom || sourceX >= sourceRight)
    return 1;
    
  // Clip the source and destination rectangles
  if (destY < 0)
  {
    sourceY -= destY;
    destY = 0;
  }
  
  // Require at least 3 pixels from left edge for shadow effect
  if (destX < 3)
  {
    sourceX -= destX;
    destX = 3;
  }
  
  if (destBottom > 240)
  {
    sourceBottom -= destBottom - 240;
    destBottom = 240;
  }
  if (destRight > 320)
  {
    sourceRight -= destRight - 320;
    destRight = 320;
  }
  
  // Adjust coordinates for horizontal flipping
  if (flipHorizontal)
  {
    flipSourceY = originalSourceY - sourceX;
    sourceX = originalSourceY - sourceRight;
    sourceRight = flipSourceY;
  }
  
  // Double-check bounds after clipping
  if (destY >= destBottom || destX >= destRight)
    return 1;
  if (sourceY >= sourceBottom || sourceX >= sourceRight)
    return 1;
  
  // Lock the source surface
  sourceSurfaceInfo[0] = 108;
  lockResult = (*(int (__stdcall **)(int, int *, int *, int, _DWORD))(*(_DWORD *)sourceSurface + 100))
                 (sourceSurface, &sourceX, sourceSurfaceInfo, 17, 0);
  if (lockResult)
    return lockResult != -2005532222;
    
  // Lock the destination surface
  destSurfaceInfo[0] = 108;
  flipResult = (*(int (__stdcall **)(_DWORD *, int *, int *, int, _DWORD))(*graphicsContext[33284] + 100))
                 (graphicsContext[33284], &destX, destSurfaceInfo, 1, 0);
  if (flipResult)
    return flipResult != -2005532222;
  
  width = destRight - destX;
  height = destBottom - destY;
  
  // Create shadow effect by copying from 3 pixels to the left
  if (transparentColor)
  {
    skipColor = transparentColor;
    
    if (flipHorizontal)
    {
      // Flipped shadow effect with transparency
      destPtr = destData;
      sourcePtr = sourceData;
      row = height - 1;
      do
      {
        col = width - 1;
        do
        {
          // Only create shadow for non-transparent source pixels
          if (skipColor != *(_BYTE *)(sourcePtr + width - 1 - col))
            *(_BYTE *)(destPtr + col) = *(_BYTE *)(destPtr + col - 3);  // Copy from 3px left
          --col;
        }
        while (col >= 0);
        sourcePtr += sourcePitch;
        destPtr += destPitch;
        --row;
      }
      while (row >= 0);
    }
    else
    {
      // Normal shadow effect with transparency
      normalDestPtr = destData;
      normalSourcePtr = sourceData;
      normalRow = height - 1;
      do
      {
        normalCol = width - 1;
        do
        {
          // Only create shadow for non-transparent source pixels
          if (skipColor != *(_BYTE *)(normalSourcePtr + normalCol))
            *(_BYTE *)(normalDestPtr + normalCol) = *(_BYTE *)(normalDestPtr + normalCol - 3);  // Copy from 3px left
          --normalCol;
        }
        while (normalCol >= 0);
        normalSourcePtr += sourcePitch;
        normalDestPtr += destPitch;
        --normalRow;
      }
      while (normalRow >= 0);
    }
  }
  else
  {
    // Direct shadow effect (no transparency checking)
    directDestPtr = destData;
    directSourcePtr = sourceData;
    directRow = height - 1;
    do
    {
      directCol = width - 1;
      do
      {
        *(_BYTE *)(directDestPtr + directCol) = *(_BYTE *)(directDestPtr + directCol - 3);  // Copy from 3px left
        --directCol;
      }
      while (directCol >= 0);
      directSourcePtr += sourcePitch;
      directDestPtr += destPitch;
      --directRow;
    }
    while (directRow >= 0);
  }
  
  // Unlock surfaces
  (*(void (__stdcall **)(_DWORD *, int))(*graphicsContext[33284] + 128))(graphicsContext[33284], destData);
  (*(void (__stdcall **)(int, int))(*(_DWORD *)sourceSurface + 128))(sourceSurface, sourceData);
  
  return 1;
}

