BOOL __thiscall upscaleScreenBuffer(_DWORD **graphicsContext)
{
  int *rect;                 // Rectangle definition
  int destRowStart;          // Start of current destination row
  int srcRowStart;           // Start of current source row
  int srcRow;                // Current source row counter
  int srcCol;                // Current source column
  int destCol;               // Current destination column
  char pixelValue;           // Value of source pixel
  int destPos1;              // First destination position
  int destPos2;              // Second destination position
  _DWORD rectCoords[4];      // Rectangle coordinates BYREF
  int left;                  // Left coordinate
  int top;                   // Top coordinate
  int right;                 // Right coordinate
  int bottom;                // Bottom coordinate
  int rowHeight;             // Height multiplier for rows
  _DWORD rectData[4];        // Rectangle data BYREF
  int result;                // Surface lock result
  int sourceWidth;           // Source width (320)
  int sourceHeight;          // Source height (240)
  int destOffset;            // Destination buffer offset
  int srcOffset;             // Source buffer offset
  int v24[4];                // Surface description BYREF
  int pitch;                 // Surface pitch (bytes per row)
  int surfacePtr;            // Pointer to surface data

  // Set up rectangle with coordinates (0,0,640,480)
  rect = setRectFromCoordinates(rectCoords, 0, 0, 640, 480);
  left = *rect;
  top = rect[1];
  right = rect[2];
  bottom = rect[3];
  
  // Copy rectangle coordinates to destination
  rectData[0] = left;
  rectData[1] = top;
  rectData[2] = right;
  rectData[3] = bottom;
  
  // Lock the surface for direct access
  v24[0] = 108;  // Size of DDSURFACEDESC struct
  result = (*(int (__stdcall **)(_DWORD *, _DWORD *, int *, int, _DWORD))
           (*graphicsContext[33284] + 100))  // IDirectDrawSurface::Lock
           (graphicsContext[33284], rectData, v24, 1, 0);
           
  if (result)
    return result != -2005532222;  // DDERR_SURFACELOST
    
  // Calculate offsets and dimensions
  surfacePtr = v26;
  srcOffset = pitch * 239 + surfacePtr;
  rowHeight = 478 * pitch;
  sourceWidth = 320;
  sourceHeight = 240;
  
  // Start at bottom-left and work upward (due to BMP format)
  destRowStart = rowHeight + surfacePtr;
  srcRowStart = 239 * pitch + surfacePtr;
  
  // Loop through each row, starting from the bottom
  for (srcRow = 239; srcRow >= 0; --srcRow)
  {
    srcCol = 319;
    destCol = 638;
    
    // Process each pixel in the row, right to left
    do
    {
      // Get the source pixel
      pixelValue = *(_BYTE *)(srcRowStart + srcCol);
      
      // Duplicate it to 4 pixels in a 2x2 pattern
      *(_BYTE *)(destRowStart + destCol) = pixelValue;
      destPos1 = destCol + 1;
      *(_BYTE *)(destRowStart + destPos1) = pixelValue;
      destPos2 = pitch + destPos1;
      *(_BYTE *)(destRowStart + destPos2--) = pixelValue;
      *(_BYTE *)(destRowStart + destPos2) = pixelValue;
      
      // Move to the next pixel
      destCol = destPos2 - pitch - 2;
      --srcCol;
    }
    while (srcCol >= 0);
    
    // Move to next row
    destRowStart = destRowStart - pitch - pitch;
    srcRowStart -= pitch;
  }
  
  // Unlock the surface
  (*(void (__stdcall **)(_DWORD *, int))(*graphicsContext[33284] + 128))
    (graphicsContext[33284], surfacePtr);
    
  return 1;
}
