// Original name: sub_40FF70
char __thiscall getScreenPositionState(int characterPtr)
{
  double characterX;             // X position of this character
  double opponentX;              // X position of opponent
  double distanceBetween;        // Distance between characters
  const double EDGE_MARGIN = 20.0;
  const double MAX_DISTANCE = 280.0;
  const double SCREEN_WIDTH = 639.0;
  const double RIGHT_BOUNDARY = 619.0; // SCREEN_WIDTH - EDGE_MARGIN
  
  // Get character and opponent X positions
  characterX = *(double *)(characterPtr + 32);
  opponentX = *(double *)(**(_DWORD **)(characterPtr + 120) + 32);
  
  // Calculate distance between characters
  distanceBetween = opponentX - characterX;
  
  // Check if at left edge: opponent at left boundary OR characters too far apart
  if ((opponentX <= EDGE_MARGIN && characterX <= opponentX + EDGE_MARGIN) || 
      distanceBetween > MAX_DISTANCE)
  {
    return 1; // Left edge or too far apart
  }
  
  // Check if at right edge: opponent at right boundary AND characters close enough
  if ((opponentX >= RIGHT_BOUNDARY && characterX + EDGE_MARGIN < SCREEN_WIDTH) && 
      distanceBetween <= MAX_DISTANCE)
  {
    return 0; // Right edge and within distance
  }
  
  // Neither edge condition met
  return -1;
}

