char __thiscall getNextActionFromBuffer(int this)
{
  __int16 actionResult; // ax
  int objectData; // [esp+0h] [ebp-8h]
  const int OPPONENT_PTR_OFFSET = 120;
  const int OPPONENT_STATE_OFFSET = 332;
  const int ACTION_BUFFER_OFFSET = 11200;
  const int ACTION_COOLDOWN_OFFSET = 11202;
  
  // First check if opponent is in a special state
  actionResult = *(_WORD *)(**(_DWORD **)(this + OPPONENT_PTR_OFFSET) + OPPONENT_STATE_OFFSET);
  if (!actionResult)
  {
    // Check if there are actions in the buffer
    if (*(_BYTE *)(this + ACTION_BUFFER_OFFSET))
    {
      // Get object data pointer
      if (this)
        objectData = this + 8;
      else
        objectData = 0;
        
      // Get next action from buffer
      LOBYTE(actionResult) = (unsigned __int8)addActionEntry((_BYTE *)(this + ACTION_BUFFER_OFFSET), objectData);
      
      // Reset cooldown
      *(_BYTE *)(this + ACTION_COOLDOWN_OFFSET) = 0;
    }
    else
    {
      // No actions in buffer, check cooldown
      LOBYTE(actionResult) = this;
      if (*(_BYTE *)(this + ACTION_COOLDOWN_OFFSET))
      {
        // Decrement cooldown and return it
        LOBYTE(actionResult) = *(_BYTE *)(this + ACTION_COOLDOWN_OFFSET) - 1;
        *(_BYTE *)(this + ACTION_COOLDOWN_OFFSET) = actionResult;
      }
    }
  }
  return actionResult;
}

