      result = entityCollection;
      if (*(__int16 *)(entityCollection + 716) == *(__int16 *)(entityCollection + 714))
        break;
        
      result = *(__int16 *)(entityCollection + 716);
      if (*(_DWORD *)(entityCollection + 4 * result + 976))
        break;
        
