/**
 * Sets an entity's velocity vector based on an angle and magnitude
 * 
 * @param entityData Pointer to entity's data structure
 * @param angleInDegrees Direction angle in degrees (0 = right, 90 = up)
 * @param magnitude Speed/force magnitude
 */
void __thiscall setVelocityFromPolarCoordinates(double *entityData, double angleInDegrees, double magnitude)
{
  const double DEGREES_TO_RADIANS = 57.29579143313326; // 180/π
  
  // Convert angle from degrees to radians and calculate velocity components
  double angleInRadians = angleInDegrees / DEGREES_TO_RADIANS;
  
  // Set X velocity component at index 5
  entityData[5] = cos(angleInRadians) * magnitude;
  
  // Set Y velocity component at index 6
  entityData[6] = sin(angleInRadians) * magnitude;
}

