/**
 * @brief Loads Nanase's alternate form pattern data from file
 *
 * Reads animation, hitbox, and physics data for Nanase's alternate form (nanase2)
 * from a pattern file. Allocates memory for entities and resources, then populates
 * them with values from the file.
 *
 * @param this Pointer to Nanase character data structure
 * @return Result of file operation
 */
int __thiscall loadNanaseAlternatePatternData(_DWORD *this)
{
  int loopIndex;            // Loop counter with multiple uses
  int entityOffset;         // Current entity memory offset
  _WORD *resourceData;      // Pointer to resource data
  int entityIndex;          // Loop counter for entities
  int patternIndex;         // Loop counter for patterns
  int entityCount;          // Number of entities for current pattern
  int patternId;            // ID of the current pattern
  HANDLE fileHandle[3];     // File handle array
  int patternCount;         // Total number of patterns to load

  // Open the pattern file for Nanase's alternate form
  initializeAndOpenFile(fileHandle, "nanase\\nanase2.pat", 1);
  
  // Read the total number of patterns in the file
  patternCount = readInt32FromFileHandle(fileHandle);
  
  // Process each pattern in the file
  for (patternIndex = 0; patternIndex < patternCount; ++patternIndex)
  {
    // Read pattern ID and set basic pattern properties
    patternId = readInt32FromFileHandle(fileHandle);
    *(_WORD *)(this[3352] + 8 * patternId) = readInt32FromFileHandle(fileHandle);
    *(_WORD *)(this[3352] + 8 * patternId + 2) = readInt32FromFileHandle(fileHandle);
    *(_BYTE *)(this[3351] + 8 * patternId) = readInt32FromFileHandle(fileHandle);
    
    // Get entity count for this pattern
    entityCount = *(unsigned __int8 *)(this[3351] + 8 * patternId);
    
    // Allocate memory for entities and resources
    allocateEntityMemory((_DWORD *)(this[3352] + 8 * patternId), entityCount);
    allocateResourceMemory((_DWORD *)(this[3351] + 8 * patternId), entityCount);
    
    // Process each entity in the pattern
    for (entityIndex = 0; entityIndex < entityCount; ++entityIndex)
    {
      // Get pointers to resource and entity data
      resourceData = (_WORD *)(*(_DWORD *)(this[3351] + 8 * patternId + 4) + 12 * entityIndex);
      entityOffset = *(_DWORD *)(this[3352] + 8 * patternId + 4) + 200 * entityIndex;
      
      // Load animation frame data
      *resourceData = 3 * readInt32FromFileHandle(fileHandle);
      resourceData[1] = readInt32FromFileHandle(fileHandle);
      resourceData[4] = readInt32FromFileHandle(fileHandle);
      resourceData[5] = readInt32FromFileHandle(fileHandle);
      resourceData[2] = readInt32FromFileHandle(fileHandle);
      resourceData[3] = readInt32FromFileHandle(fileHandle);
      
      // Load entity properties
      *(_WORD *)(entityOffset + 160) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 170) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 172) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 176) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 178) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 168) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 180) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 182) = readInt32FromFileHandle(fileHandle);
      
      // Load and scale physics parameters
      *(float *)(entityOffset + 188) = (float)readInt16FromFileHandle(fileHandle);
      *(float *)(entityOffset + 188) = *(float *)(entityOffset + 188) / 100.0;
      *(float *)(entityOffset + 184) = (float)readInt16FromFileHandle(fileHandle);
      *(float *)(entityOffset + 184) = *(float *)(entityOffset + 184) / -100.0;
      
      // Load additional entity attributes
      *(_BYTE *)(entityOffset + 193) = readInt16FromFileHandle(fileHandle);
      *(_BYTE *)(entityOffset + 192) = readInt16FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 194) = readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 196) = readInt32FromFileHandle(fileHandle);
      *(float *)(entityOffset + 164) = (float)readInt32FromFileHandle(fileHandle);
      *(_WORD *)(entityOffset + 174) = readInt32FromFileHandle(fileHandle);
      
      // Load hitbox data blocks
      readBytesFromFileHandle(fileHandle, (LPVOID)(entityOffset + 144), 0x10u);
      
      // Load first two animation data blocks
      for (loopIndex = 0; loopIndex < 2; ++loopIndex)
        readBytesFromFileHandle(fileHandle, (LPVOID)(entityOffset + 16 * loopIndex), 0x10u);
      
      // Load middle animation data block
      readBytesFromFileHandle(fileHandle, (LPVOID)(entityOffset + 80), 0x10u);
      
      // Load remaining animation data blocks
      for (loopIndex = 2; loopIndex < 5; ++loopIndex)
        readBytesFromFileHandle(fileHandle, (LPVOID)(entityOffset + 16 * loopIndex), 0x10u);
      
      // Load additional hitbox data blocks
      for (loopIndex = 1; loopIndex < 4; ++loopIndex)
        readBytesFromFileHandle(fileHandle, (LPVOID)(entityOffset + 16 * loopIndex + 80), 0x10u);
    }
  }
  
  // Close the file and clean up
  return closeAndCleanupFile(fileHandle);
}
