/**
 * @brief Renders Nanase's special gauge on the screen
 *
 * Displays Nanase's special meter during gameplay with appropriate positioning
 * based on player side (P1/P2). First renders the gauge background, then draws
 * the actual gauge with a width proportional to its current value.
 *
 * @param this Pointer to Nanase character data
 * @return Success status of rendering operation
 */
BOOL __thiscall renderNanaseSpecialGauge(int this)
{
  int *srcImagePtr;         // Source image data pointer
  int *rectPtr;             // Rectangle data pointer
  BOOL result;              // Function result
  _DWORD srcRect[4];        // Source rectangle for background
  int dstX;                 // Destination X coordinate
  int dstY;                 // Destination Y coordinate
  int width;                // Rectangle width
  int height;               // Rectangle height
  _DWORD gaugeSrcRect[4];   // Source rectangle for gauge
  int gaugeWidth;           // Gauge display width based on current value
  _DWORD tempRect[4];       // Temporary rectangle storage
  int srcResource;          // Source resource index
  int srcOffset;            // Source data offset
  int srcWidth;             // Source image width
  int srcHeight;            // Source image height
  
  // Check if the gauge value is greater than zero
  if (*(int *)(this + 12616) > 0)
  {
    // Get gauge background image information
    srcImagePtr = *(int **)(*(_DWORD *)(this + 16) + 348);
    srcResource = *srcImagePtr;
    srcOffset = srcImagePtr[1];
    srcWidth = srcImagePtr[2];
    
    // Create source rectangle for the gauge background
    rectPtr = setRectFromCoordinates(srcRect, 0, 0, (__int16)srcWidth, SHIWORD(srcWidth));
    dstX = *rectPtr;
    dstY = rectPtr[1];
    width = rectPtr[2];
    height = rectPtr[3];
    
    // Store source rectangle values for later use
    tempRect[0] = dstX;
    tempRect[1] = dstY;
    tempRect[2] = width;
    tempRect[3] = height;
    
    // Determine destination coordinates based on player side
    if (*(_BYTE *)(this + 140)) // If P2 side
    {
      // Position gauge on right side of screen
      rectPtr = setRectFromCoordinates(
        gaugeSrcRect,
        (__int16)srcOffset + 271 - (__int16)srcWidth,
        31 - SHIWORD(srcOffset),
        (__int16)srcWidth,
        SHIWORD(srcWidth));
    }
    else // If P1 side
    {
      // Position gauge on left side of screen
      rectPtr = setRectFromCoordinates(
        gaugeSrcRect,
        49 - (__int16)srcOffset,
        31 - SHIWORD(srcOffset),
        (__int16)srcWidth,
        SHIWORD(srcWidth));
    }
    
    // Set destination rectangle values
    dstX = *rectPtr;
    dstY = rectPtr[1];
    width = rectPtr[2];
    height = rectPtr[3];
    
    // Render gauge background
    blitSurfaceWithTransparency(
      *(_DWORD ***)(this + 128),
      dstX,
      dstY,
      width,
      height,
      *(_DWORD *)(*(_DWORD *)(this + 20) + 4 * HIWORD(srcResource)),
      tempRect[0],
      tempRect[1],
      tempRect[2],
      tempRect[3],
      *(_BYTE *)(this + 26),
      0);
  }
  
  result = this;
  
  // Check again if gauge value is greater than zero
  if (*(int *)(this + 12616) > 0)
  {
    // Get gauge fill image information
    srcImagePtr = *(int **)(*(_DWORD *)(this + 16) + 356);
    srcResource = *srcImagePtr;
    srcOffset = srcImagePtr[1];
    srcWidth = srcImagePtr[2];
    
    // Calculate gauge width proportional to current value (max 3000)
    gaugeWidth = *(_DWORD *)(this + 12616) * (__int16)srcWidth / 3000;
    
    // Create source rectangle for the gauge fill
    rectPtr = setRectFromCoordinates(gaugeSrcRect, 0, 0, gaugeWidth, SHIWORD(srcWidth));
    dstX = *rectPtr;
    dstY = rectPtr[1];
    width = rectPtr[2];
    height = rectPtr[3];
    
    // Store source rectangle values
    tempRect[0] = dstX;
    tempRect[1] = dstY;
    tempRect[2] = width;
    tempRect[3] = height;
    
    // Determine destination coordinates based on player side
    if (*(_BYTE *)(this + 140)) // If P2 side
    {
      // Position gauge fill on right side of screen
      rectPtr = setRectFromCoordinates(
        srcRect,
        (__int16)srcOffset + 271 - gaugeWidth,
        31 - SHIWORD(srcOffset),
        gaugeWidth,
        SHIWORD(srcWidth));
    }
    else // If P1 side
    {
      // Position gauge fill on left side of screen
      rectPtr = setRectFromCoordinates(
        tempRect,
        49 - (__int16)srcOffset,
        31 - SHIWORD(srcOffset),
        gaugeWidth,
        SHIWORD(srcWidth));
    }
    
    // Set destination rectangle values
    dstX = *rectPtr;
    dstY = rectPtr[1];
    width = rectPtr[2];
    height = rectPtr[3];
    
    // Render the gauge fill
    return blitSurfaceWithTransparency(
             *(_DWORD ***)(this + 128),
             dstX,
             dstY, 
             width,
             height,
             *(_DWORD *)(*(_DWORD *)(this + 20) + 4 * HIWORD(srcResource)),
             tempRect[0],
             tempRect[1],
             tempRect[2],
             tempRect[3],
             *(_BYTE *)(this + 26),
             0);
  }
  
  return result;
}
