      for (patternIndex = 0; patternIndex < 2; ++patternIndex)
        readBytesFromFileHandle(fileHandle, (LPVOID)(entityPtr + 16 * patternIndex), 0x10u);
        
      // Read throw box
      readBytesFromFileHandle(fileHandle, (LPVOID)(entityPtr + 80), 0x10u);
      
      // Read additional collision boxes
      for (propertyIndex3 = 2; propertyIndex3 < 5; ++propertyIndex3)
        readBytesFromFileHandle(fileHandle, (LPVOID)(entityPtr + 16 * propertyIndex3), 0x10u);
        
