  _itoa(*(__int16 *)(backgroundContext + 4), backgroundIDStr, 10);
  strcat(filePath, backgroundIDStr);
  
  // Add the filename part (again with zero padding if needed)
  if (*(__int16 *)(backgroundContext + 4) < 10)
    strcat(filePath, "\\bg0");
  else
    strcat(filePath, "\\bg");
  
  // Finish building the pattern file path
  strcat(filePath, backgroundIDStr);
  strcat(filePath, ".pat");
  
  // Open the pattern file
  initializeAndOpenFile(fileHandle, filePath, 1);
  
  // Read the count of patterns
  tempPatternCount = readInt32FromFileHandle(fileHandle);
  patternCount = tempPatternCount;
  
