int __thiscall updateStage16BackgroundAnimation(_DWORD *backgroundContext)
{
  int result;                // Return value
  int layerIndex;            // Loop counter for layers
  
  // Process all four background layers
  for (layerIndex = 0; layerIndex < 4; ++layerIndex)
  {
    // Each layer has a different movement behavior based on its ID
    switch (*(_WORD *)(backgroundContext[4] + 112 * layerIndex))
    {
      case 0:  // Furthest background layer - slowest movement
        // Move this layer horizontally
        *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 
            *(double *)(backgroundContext[4] + 112 * layerIndex + 24) + 1.0;
            
        // Wrap around when reaching the edge (850 pixels wide)
        if (*(double *)(backgroundContext[4] + 112 * layerIndex + 24) >= 850.0)
          *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 
              *(double *)(backgroundContext[4] + 112 * layerIndex + 24) - 850.0;
        break;
        
      case 1:  // Second layer - slightly faster movement
        // Move this layer horizontally at 1.4 pixels per frame
        *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 
            *(double *)(backgroundContext[4] + 112 * layerIndex + 24) + 1.4;
            
        // Wrap around when reaching the edge (806 pixels wide)
        if (*(double *)(backgroundContext[4] + 112 * layerIndex + 24) >= 806.0)
          *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 
              *(double *)(backgroundContext[4] + 112 * layerIndex + 24) - 806.0;
        break;
        
      case 2:  // Third layer - even faster movement
        // Move this layer horizontally at 1.8 pixels per frame
        *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 
            *(double *)(backgroundContext[4] + 112 * layerIndex + 24) + 1.8;
            
        // Wrap around when reaching the edge (789 pixels wide)
        if (*(double *)(backgroundContext[4] + 112 * layerIndex + 24) >= 789.0)
          *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 
              *(double *)(backgroundContext[4] + 112 * layerIndex + 24) - 789.0;
        break;
        
      case 3:  // Nearest foreground layer - fastest movement
        // Move this layer horizontally at 2.2 pixels per frame
        *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 
            *(double *)(backgroundContext[4] + 112 * layerIndex + 24) + 2.2;
            
        // Stop at the right edge (no wrap for this layer)
        if (*(double *)(backgroundContext[4] + 112 * layerIndex + 24) >= 947.0)
          *(double *)(backgroundContext[4] + 112 * layerIndex + 24) = 947.0;
        break;
        
      default:  // Unknown layer type
        break;
    }
    
    result = layerIndex + 1;  // Return count of layers we've processed
  }
  
  return result;
}

