/**
 * Loads the stage graphics and palette data for the current battle
 * 
 * @param gameContext Pointer to the game context
 * @return Result of setting the palette range
 */
int __thiscall loadStageGraphics(int gameContext)
{
  char stageIndexStr[8]; // [esp+14h] [ebp-34h] BYREF
  char filePath[40]; // [esp+1Ch] [ebp-2Ch] BYREF
  
  // Build stage file path based on stage index
  if (*(char *)(*(_DWORD *)(gameContext + 28) + 3890) >= 10)
    strcpy(filePath, "system\\stage\\");
  else
    strcpy(filePath, "system\\stage\\0"); // Pad with 0 for single-digit stages
    
  _itoa(*(char *)(*(_DWORD *)(gameContext + 28) + 3890), stageIndexStr, 10);
  strcat(filePath, stageIndexStr);
  strcat(filePath, ".dat");
  
  // Load stage graphics and palette data
  loadCompressedImageFile(*(_DWORD ****)(gameContext + 28), (_DWORD *)(gameContext + 1084), 
                        filePath, 0, 191);
  loadBGRColorsFromRawFile(gameContext + 46, filePath, 0, 191, 64);
  
  // Store the key pixel value from stage graphics
  *(_BYTE *)(gameContext + 1103) = readPixelValue(*(_DWORD *)(gameContext + 1084));
  
  // Set up the palette range for the stage
  return setPaletteRange(*(_DWORD ***)(gameContext + 32), gameContext + 46, 0xAFu, 0x50u);
}

//----- (007595D0) --------------------------------------------------------
// Original name: sub_7595D0
/**
 * Reloads the character's palette data from their data file
 * 
 * @param gameContext Pointer to the game context
 * @param playerIndex Player index (0 for P1, 1 for P2)
 * @return Result of setting the palette range
 */
int __thiscall reloadCharacterPalette(_DWORD ***gameContext, char playerIndex)
{
  char filePath[40]; // [esp+4h] [ebp-2Ch] BYREF
  
  // Build path to character data file
  strcpy(filePath, "system\\");
  strcat(filePath, (const char *)gameContext[playerIndex + 3] + 148); // Character name
  strcat(filePath, "\\");
  strcat(filePath, (const char *)gameContext[playerIndex + 3] + 148);
  strcat(filePath, ".dat");
  
  // Load character palette data
  loadBGRColorsFromRawFile((int)gameContext + 46, filePath, 
                         40 * *((char *)gameContext + playerIndex + 1342), 40 * playerIndex + 175, 40);
                         
  // Set the palette range for this character
  return setPaletteRange(gameContext[8], (int)gameContext + 46, 40 * playerIndex - 81, 0x28u);
}

