/**
 * Handles keyboard input for the control settings screen
 * 
 * @param gameContext Pointer to the game context
 * @return Status of control preset loading
 */
char __thiscall handleControlSettingsInput(int gameContext)
{
  char result; // al
  _BYTE inputState[62]; // [esp+8h] [ebp-108h] BYREF
  char keyF10State; // [esp+46h] [ebp-CAh]
  
  // Get the keyboard input state
  if ((*(int (__stdcall **)(_DWORD, int, _BYTE *))(**(_DWORD **)(*(_DWORD *)(gameContext + 36) + 488) + 36))(
         *(_DWORD *)(*(_DWORD *)(gameContext + 36) + 488),
         256,
         inputState) == -2147024866)
  {
    // Reacquire the input device if needed
    (*(void (__stdcall **)(_DWORD))(**(_DWORD **)(*(_DWORD *)(gameContext + 36) + 488) + 28))(
        *(_DWORD *)(*(_DWORD *)(gameContext + 36) + 488));
  }
  
  // Check for ESC key press
  if ((inputState[1] & 0x80) != 0)
    *(_BYTE *)(gameContext + 45) = 1;
    
  // Check for F1 key press - reload control bindings
  if ((inputState[59] & 0x80) != 0)
    loadControlBindings(*(_WORD **)(gameContext + 36));
    
  // Check for F2 key press - load preset 1
  if ((inputState[60] & 0x80) != 0 && readConfigByte(0x98u))
    loadControlPreset(*(_WORD **)(gameContext + 36), 1);
    
  // Check for F3 key press - load preset 2  
  if ((inputState[61] & 0x80) != 0 && readConfigByte(0x98u))
    loadControlPreset(*(_WORD **)(gameContext + 36), 2);
    
  // Check for F10 key press - load preset 3
  result = keyF10State & 0x80;
  if (keyF10State < 0)
  {
    result = readConfigByte(0x98u);
    if (result)
      return loadControlPreset(*(_WORD **)(gameContext + 36), 3);
  }
  
  return result;
}

