/**
 * Performs a rotating transition animation
 * 
 * Creates a smooth rotating animation effect over 360 degrees.
 * At the half-way point (180 degrees), loads character data.
 * 
 * @param screenContext    Pointer to screen context
 * @return                 Time value when animation completes
 */
DWORD __thiscall performRotatingTransitionAnimation(void (__thiscall ***screenContext)(void *))
{
  DWORD result;          // Return value
  int angle;             // Current animation angle
  DWORD frameTime;       // Time tracking for frame limiting
  int frameSkip;         // Toggle for frame skipping (performance)

  // Start time measurement
  result = timeGetTime();
  frameTime = result;
  frameSkip = 0;
  
  // Loop through 360 degrees in 10-degree increments
  for (angle = 0; angle <= 360; angle += 10)
  {
    // Render the current frame
    (**screenContext)(screenContext);
    
    // Calculate X position offset using cosine wave (oscillates left to right)
    // 160 is screen center X, cosine creates wave effect scaled by 160
    screenContext[468] = (void (__thiscall **)(void *))(unsigned __int64)
                          (160.0 - cos((double)angle / 57.29579143313326) * 160.0);
    
    // At the halfway point, load character data and update palette
    if (angle == 180)
    {
      loadCharacterDataAndGraphics((int)screenContext);
      setPalette((_DWORD **)screenContext[8], (int)screenContext + 46);
    }
    
    // Frame limiting (target ~60fps)
    while (timeGetTime() - frameTime < (unsigned __int8)(16 - frameSkip))
      ;
      
    frameTime = timeGetTime();
    LOBYTE(frameSkip) = frameSkip == 0;  // Toggle frame skip
    result = angle + 10;
  }
  
  // Reset position offset when animation completes
  screenContext[468] = 0;
  return result;
}

//----- (0075D660) --------------------------------------------------------
// Original name: sub_75D660
/**
 * Fades to a loading screen image
 * 
 * Performs a smooth fade-out transition, loads a random loading screen image,
 * then performs a fade-in transition.
 * 
 * @param screenContext    Pointer to screen context
 * @return                 Result from the animation (frame skip value)
 */
int __thiscall fadeToLoadingScreen(int *screenContext)
{
  int result;             // Return value
  DWORD frameTime;        // Time tracking for frame limiting
  char numBuffer[20];     // Buffer for string conversion
  int step;               // Animation step counter
  BOOL frameSkip;         // Toggle for frame skipping (performance)
  char filePath[52];      // Buffer for file path construction

  // Start time measurement
  frameTime = timeGetTime();
  frameSkip = 0;
  
  // Fade out (10 steps, getting darker each step)
  for (step = 10; step >= 0; --step)
  {
    // Render current frame
    (*(void (__thiscall **)(int *))*screenContext)(screenContext);
    
    // Create darkening effect (gets darker as step decreases)
    createDarkenedPalette(
      (_DWORD **)screenContext[8],        // Graphics context
      (int)screenContext + 46,            // Palette data
      0,                                  // First color index
      0xFFu,                              // Last color index
      10 * step);                         // Brightness percentage (100% to 0%)
    
    // Frame limiting (target ~60fps)
    while (timeGetTime() - frameTime < (unsigned __int8)(16 - frameSkip))
      ;
      
    frameTime = timeGetTime();
    frameSkip = !frameSkip;  // Toggle frame skip
  }
  
  // Construct path to loading screen image (nl = "Next Loading")
  strcpy(filePath, "system\\nl\\nl");
  
  // Add zero padding for numbers less than 100/10
  if (screenContext[470] < 100)
    strcat(filePath, "0");
  if (screenContext[470] < 10)
    strcat(filePath, "0");
    
  // Convert loading screen number to string
  _itoa(screenContext[470], numBuffer, 10);
  strcat(filePath, numBuffer);
  
  // Free previous loading screen if it exists
  if (screenContext[273])
  {
    (*(void (__stdcall **)(int))(*(_DWORD *)screenContext[273] + 8))(screenContext[273]);
    screenContext[273] = 0;
  }
  
  // Complete the file path and load the image
  strcat(filePath, ".dat");
  loadCompressedImageFile(
    (_DWORD ***)screenContext[7],         // Graphics manager
    screenContext + 273,                  // Destination surface
    filePath,                             // File path
    0,                                    // Color offset 1
    1);                                   // Color offset 2
    
  // Load palette data
  result = loadBGRColorsFromRawFile(
    (int)screenContext + 46,              // Destination palette
    filePath,                             // File path
    0,                                    // Source start index
    1,                                    // Destination start index
    254);                                 // Color count
    
  // Set screen state to 2 (loading screen)
  *((_BYTE *)screenContext + 1101) = 2;
  
  // Fade in (0 to 10 steps, getting brighter each step)
  for (step = 0; step <= 10; ++step)
  {
    // Render current frame
    (*(void (__thiscall **)(int *))*screenContext)(screenContext);
    
    // Create darkening effect (gets brighter as step increases)
    createDarkenedPalette(
      (_DWORD **)screenContext[8],        // Graphics context
      (int)screenContext + 46,            // Palette data
      0,                                  // First color index
      0xFFu,                              // Last color index
      10 * step);                         // Brightness percentage (0% to 100%)
    
    // Frame limiting (target ~60fps)
    while (timeGetTime() - frameTime < (unsigned __int8)(16 - frameSkip))
      ;
      
    frameTime = timeGetTime();
    result = !frameSkip;
    frameSkip = result;  // Toggle frame skip
  }
  
  return result;
}

