// Original name: sub_75DA30
/**
 * Performs a slide-in or slide-out animation effect
 * 
 * Creates a smooth slide animation using cosine curves for easing.
 * 
 * @param screenContext    Pointer to screen context
 * @param slideDirection   0 for slide-in, non-zero for slide-out
 * @return                 Result from the animation (frame skip value)
 */
int __thiscall performSlideAnimation(void (__thiscall ***screenContext)(void *), unsigned __int8 slideDirection)
{
  int result;          // Return value
  int angle;           // Current animation angle
  int i;               // Loop counter
  DWORD frameTime;     // Time tracking for frame limiting
  int frameSkip;       // Toggle for frame skipping (performance)

  frameTime = timeGetTime();
  frameSkip = 0;
  result = slideDirection;
  
  if (slideDirection)
  {
    // Slide-out animation (90° to 0° by 5° steps)
    for (angle = 90; angle >= 0; angle -= 5)
    {
      // Render current frame
      (**screenContext)(screenContext);
      
      // Calculate slide position using cosine curve for smooth motion
      // 1.0 - cos(angle) gives a smooth curve from 0 to 320
      screenContext[469] = (void (__thiscall **)(void *))(__int16)(unsigned __int64)(
        (1.0 - cos((double)angle / 57.29579143313326)) * 320.0);
      
      // Frame limiting (target ~60fps)
      while (timeGetTime() - frameTime < (unsigned __int8)(16 - frameSkip))
        ;
        
      frameTime = timeGetTime();
      result = frameSkip == 0;
      frameSkip = result;
    }
  }
  else
  {
    // Slide-in animation (0° to 90° by 5° steps)
    for (i = 0; i <= 90; i += 5)
    {
      // Render current frame
      (**screenContext)(screenContext);
      
      // Calculate slide position using cosine curve for smooth motion
      screenContext[469] = (void (__thiscall **)(void *))(__int16)(unsigned __int64)(
        (1.0 - cos((double)i / 57.29579143313326)) * 320.0);
      
      // Frame limiting (target ~60fps)
      while (timeGetTime() - frameTime < (unsigned __int8)(16 - frameSkip))
        ;
        
      frameTime = timeGetTime();
      result = frameSkip == 0;
      frameSkip = result;
    }
  }
  
  return result;
}
