// Original name: sub_75DB70
/**
 * Renders a multi-digit number on screen using digit sprites
 * 
 * @param gameContext Pointer to the game context
 * @param rightEdgeX Right edge X-coordinate for the rightmost digit
 * @param topY Top Y-coordinate for the digits
 * @param number The number to display
 * @param digitSetIndex Index of the digit sprite set to use (selects different font styles)
 * @param spacing Space between digits
 * @param usePaletteMapping Flag to use palette mapping (1) or transparency (0)
 * @return The number of remaining digits (always 0, used in recursion)
 */
unsigned int __thiscall renderNumberWithDigits(
        int gameContext,
        int rightEdgeX,
        int topY,
        unsigned int number,
        unsigned __int8 digitSetIndex,
        unsigned __int8 spacing,
        int usePaletteMapping)
{
  unsigned int remainingDigits; // Return value for the digit division
  int digitSourceY;             // Y position of the digit in the sprite sheet
  int digitHeight;              // Height of the digit sprite
  int digitSourceX;             // X position of the digit in the sprite sheet
  int digitWidth;               // Width of the digit sprite
  int bottomY;                  // Bottom Y-coordinate for drawing the digit
  int leftX;                    // Left X-coordinate for drawing the digit

  do
  {
    // Get sprite information for the selected digit set
    digitSourceY = *(_DWORD *)(gameContext + 16 * digitSetIndex + 1128);       // Top of digit in sprite sheet
    digitHeight = *(_DWORD *)(gameContext + 16 * digitSetIndex + 1136);        // Height of digit
    digitWidth = *(_DWORD *)(gameContext + 16 * digitSetIndex + 1132);         // Width of digit
    
    // Calculate source coordinates for the current digit (number % 10)
    digitSourceX = (number % 10) * digitWidth;                                 // X position in sprite sheet
    
    // Calculate destination coordinates for drawing
    bottomY = topY + digitHeight - digitSourceY;                               // Bottom edge
    leftX = rightEdgeX - digitWidth;                                           // Left edge
    
    // Draw the digit using appropriate method
    if (usePaletteMapping)
    {
      // Draw using palette mapping for special effects
      blitSurfaceWithPaletteMapping(
        *(_DWORD ***)(gameContext + 32),                     // Graphics context
        leftX,                                               // Destination left
        topY,                                                // Destination top
        rightEdgeX,                                          // Destination right
        bottomY,                                             // Destination bottom
        *(_DWORD *)(*(_DWORD *)(gameContext + 28) + 3744),  // Source surface
        digitSourceX,                                        // Source left
        digitSourceY,                                        // Source top
        digitSourceX + digitWidth,                           // Source right
        digitHeight,                                         // Source bottom
        *(_BYTE *)(*(_DWORD *)(gameContext + 28) + 3892),   // Transparent color
        0,                                                   // No flip
        0);                                                  // Palette mapping index
    }
    else
    {
      // Draw with transparency
      blitSurfaceWithTransparency(
        *(_DWORD ***)(gameContext + 32),                     // Graphics context
        leftX,                                               // Destination left
        topY,                                                // Destination top
        rightEdgeX,                                          // Destination right
        bottomY,                                             // Destination bottom
        *(_DWORD *)(*(_DWORD *)(gameContext + 28) + 3744),  // Source surface
        digitSourceX,                                        // Source left
        digitSourceY,                                        // Source top
        digitSourceX + digitWidth,                           // Source right
        digitHeight,                                         // Source bottom
        *(_BYTE *)(*(_DWORD *)(gameContext + 28) + 3892),   // Transparent color
        0);                                                  // No flip
    }
    
    // Move to the next digit position (to the left)
    rightEdgeX -= spacing + digitWidth;
    
    // Divide by 10 to process the next digit
    remainingDigits = number / 10;
    number /= 10;
  }
  while (number); // Continue until all digits are processed
  
  return remainingDigits; // Always 0 when function completes
}
