  // Smooth animation for player 2's target health display
  if (*(_DWORD *)(player2 + 272) > *(_DWORD *)(player2 + 264))
  {
    *(_DWORD *)(player2 + 272) -= 200;
    if (*(_DWORD *)(player2 + 272) < *(_DWORD *)(player2 + 264))
      *(_DWORD *)(player2 + 272) = *(_DWORD *)(player2 + 264);
  }
  if (*(_DWORD *)(player2 + 272) < *(_DWORD *)(player2 + 264))
  {
    *(_DWORD *)(player2 + 272) += 200;
    if (*(_DWORD *)(player2 + 272) > *(_DWORD *)(player2 + 264))
      *(_DWORD *)(player2 + 272) = *(_DWORD *)(player2 + 264);
  }
  
  // Gradually decrease combo damage display for player 2 when player 1 is not in a combo
  if (!*(_WORD *)(player1 + 372))  // If player 1 not in combo
  {
    *(_DWORD *)(player2 + 268) -= 100 * (*(_DWORD *)(player2 + 268) > *(_DWORD *)(player2 + 264));
    if (*(_DWORD *)(player2 + 268) < *(_DWORD *)(player2 + 264))
      *(_DWORD *)(player2 + 268) = *(_DWORD *)(player2 + 264);
  }
  
  result = gameSystem;
  
  // Only render HUD if timer value is valid (indicates we're in a match)
