// Original name: sub_7623B0
/**
 * Renders the player statistics panel showing combo count, score and damage
 * 
 * @param gameSystem Pointer to the game system
 * @param playerData Pointer to the player data
 * @return TRUE if rendering was successful
 */
BOOL __thiscall renderPlayerStatsPanel(int gameSystem, int playerData)
{
  int *rectPtr;                // Rectangle helper pointer
  signed int comboCount;       // Current combo counter (capped at 99)
  
  // Rectangle storage for source and destination rectangles
  _DWORD srcRect[4];           // Source rectangle for blit operations
  int srcLeft;                 // Left coordinate
  int srcTop;                  // Top coordinate
  int srcRight;                // Right coordinate 
  int srcBottom;               // Bottom coordinate
  
  _DWORD destRect[4];          // Destination rectangle for blit operations
  int destLeft;                // Left coordinate
  int destTop;                  // Top coordinate
  int destRight;               // Right coordinate
  int destBottom;              // Bottom coordinate
  
  // Get combo count from player data and cap it at 99
  comboCount = *(__int16 *)(playerData + 244);
  if (comboCount > 99)
    comboCount = 99;
  
  // Check player facing direction to determine which side of screen to render on
  if (*(char *)(playerData + 140) <= 0)
  {
    // Player is facing left - render stats panel on left side of screen
    
    // Setup source rectangle for panel background
    rectPtr = setRectFromCoordinates(srcRect, 0, 172, 61, 38);
    srcLeft = *rectPtr;
    srcTop = rectPtr[1];
    srcRight = rectPtr[2];
    srcBottom = rectPtr[3];
    
    // Store rectangle for reuse
    int backgroundSrcLeft = srcLeft;
    int backgroundSrcTop = srcTop;
    int backgroundSrcRight = srcRight;
    int backgroundSrcBottom = srcBottom;
    
    // Setup destination rectangle for panel
    rectPtr = setRectFromCoordinates(destRect, 6, 63, 61, 38);
    destLeft = *rectPtr;
    destTop = rectPtr[1];
    destRight = rectPtr[2];
    destBottom = rectPtr[3];
    
    int backgroundDestLeft = destLeft;
    int backgroundDestTop = destTop;
    int backgroundDestRight = destRight;
    int backgroundDestBottom = destBottom;
    
    // Draw panel background with appropriate rendering based on stun state
    if (*(__int16 *)(playerData + 260) > 6)
    {
      // Normal rendering
      blitSurfaceWithTransparency(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0);
    }
    else
    {
      // Special palette rendering when stunned
      blitSurfaceWithPaletteMapping(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0,
        0);
    }
    
    // Determine if we should use special palette for numbers
    int usePaletteMapping = (*(__int16 *)(playerData + 260) <= 6);
    
    // Render combo count with larger digits
    renderNumberWithDigits(
      gameSystem, 
      34,    // right edge X position
      59,    // Y position
      comboCount, 
      1u,    // digit set index (larger digits)
      0,     // no spacing between digits
      usePaletteMapping);
    
    // Render score value with smaller digits
    renderNumberWithDigits(
      gameSystem,
      33,    // right edge X position
      82,    // Y position
      *(_DWORD *)(playerData + 256),    // score value
      2u,    // digit set index (smaller digits)
      0,     // no spacing
      usePaletteMapping);
    
    // Render damage value (whole part) with smaller digits
    renderNumberWithDigits(
      gameSystem,
      23,    // right edge X position
      92,    // Y position
      (unsigned __int64)*(double *)(playerData + 248),  // damage value (integer part)
      2u,    // digit set index
      0,     // no spacing
      usePaletteMapping);
    
    // Render damage value (decimal part) with smaller digits
    renderNumberWithDigits(
      gameSystem,
      33,    // right edge X position
      92,    // Y position
      (int)(unsigned __int64)(*(double *)(playerData + 248) * 10.0) % 10,  // decimal part
      2u,    // digit set index
      0,     // no spacing
      usePaletteMapping);
    
    // Setup source rectangle for decimal point
    rectPtr = setRectFromCoordinates(srcRect, 70, 225, 3, 9);
    srcLeft = *rectPtr;
    srcTop = rectPtr[1];
    srcRight = rectPtr[2];
    srcBottom = rectPtr[3];
    
    backgroundSrcLeft = srcLeft;
    backgroundSrcTop = srcTop;
    backgroundSrcRight = srcRight;
    backgroundSrcBottom = srcBottom;
    
    // Setup destination rectangle for decimal point
    rectPtr = setRectFromCoordinates(destRect, 23, 92, 3, 9);
    destLeft = *rectPtr;
    destTop = rectPtr[1];
    destRight = rectPtr[2];
    destBottom = rectPtr[3];
    
    backgroundDestLeft = destLeft;
    backgroundDestTop = destTop;
    backgroundDestRight = destRight;
    backgroundDestBottom = destBottom;
    
    // Draw decimal point with appropriate rendering based on stun state
    if (*(__int16 *)(playerData + 260) > 6)
    {
      // Normal rendering
      return blitSurfaceWithTransparency(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0);
    }
    else
    {
      // Special palette rendering when stunned
      return blitSurfaceWithPaletteMapping(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0,
        0);
    }
  }
  else
  {
    // Player is facing right - render stats panel on right side of screen
    
    // Setup source rectangle for panel background
    rectPtr = setRectFromCoordinates(srcRect, 0, 172, 61, 38);
    srcLeft = *rectPtr;
    srcTop = rectPtr[1];
    srcRight = rectPtr[2];
    srcBottom = rectPtr[3];
    
    // Store rectangle for reuse
    int backgroundSrcLeft = srcLeft;
    int backgroundSrcTop = srcTop;
    int backgroundSrcRight = srcRight;
    int backgroundSrcBottom = srcBottom;
    
    // Setup destination rectangle for panel
    rectPtr = setRectFromCoordinates(destRect, 258, 63, 61, 38);
    destLeft = *rectPtr;
    destTop = rectPtr[1];
    destRight = rectPtr[2];
    destBottom = rectPtr[3];
    
    int backgroundDestLeft = destLeft;
    int backgroundDestTop = destTop;
    int backgroundDestRight = destRight;
    int backgroundDestBottom = destBottom;
    
    // Draw panel background with appropriate rendering based on stun state
    if (*(__int16 *)(playerData + 260) > 6)
    {
      // Normal rendering
      blitSurfaceWithTransparency(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0);
    }
    else
    {
      // Special palette rendering when stunned
      blitSurfaceWithPaletteMapping(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0,
        0);
    }
    
    // Determine if we should use special palette for numbers
    int usePaletteMapping = (*(__int16 *)(playerData + 260) <= 6);
    
    // Render combo count with larger digits
    renderNumberWithDigits(
      gameSystem, 
      286,   // right edge X position
      59,    // Y position
      comboCount, 
      1u,    // digit set index (larger digits)
      0,     // no spacing between digits
      usePaletteMapping);
    
    // Render score value with smaller digits
    renderNumberWithDigits(
      gameSystem,
      285,   // right edge X position
      82,    // Y position
      *(_DWORD *)(playerData + 256),    // score value
      2u,    // digit set index (smaller digits)
      0,     // no spacing
      usePaletteMapping);
    
    // Render damage value (whole part) with smaller digits
    renderNumberWithDigits(
      gameSystem,
      275,   // right edge X position
      92,    // Y position
      (unsigned __int64)*(double *)(playerData + 248),  // damage value (integer part)
      2u,    // digit set index
      0,     // no spacing
      usePaletteMapping);
    
    // Render damage value (decimal part) with smaller digits
    renderNumberWithDigits(
      gameSystem,
      285,   // right edge X position
      92,    // Y position
      (int)(unsigned __int64)(*(double *)(playerData + 248) * 10.0) % 10,  // decimal part
      2u,    // digit set index
      0,     // no spacing
      usePaletteMapping);
    
    // Setup source rectangle for decimal point
    rectPtr = setRectFromCoordinates(srcRect, 70, 225, 3, 9);
    srcLeft = *rectPtr;
    srcTop = rectPtr[1];
    srcRight = rectPtr[2];
    srcBottom = rectPtr[3];
    
    backgroundSrcLeft = srcLeft;
    backgroundSrcTop = srcTop;
    backgroundSrcRight = srcRight;
    backgroundSrcBottom = srcBottom;
    
    // Setup destination rectangle for decimal point
    rectPtr = setRectFromCoordinates(destRect, 275, 92, 3, 9);
    destLeft = *rectPtr;
    destTop = rectPtr[1];
    destRight = rectPtr[2];
    destBottom = rectPtr[3];
    
    backgroundDestLeft = destLeft;
    backgroundDestTop = destTop;
    backgroundDestRight = destRight;
    backgroundDestBottom = destBottom;
    
    // Draw decimal point with appropriate rendering based on stun state
    if (*(__int16 *)(playerData + 260) > 6)
    {
      // Normal rendering
      return blitSurfaceWithTransparency(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0);
    }
    else
    {
      // Special palette rendering when stunned
      return blitSurfaceWithPaletteMapping(
        *(_DWORD ***)(gameSystem + 32),
        backgroundDestLeft,
        backgroundDestTop,
        backgroundDestRight,
        backgroundDestBottom,
        *(_DWORD *)(*(_DWORD *)(gameSystem + 28) + 3744),
        backgroundSrcLeft,
        backgroundSrcTop,
        backgroundSrcRight,
        backgroundSrcBottom,
        *(_BYTE *)(*(_DWORD *)(gameSystem + 28) + 3892),
        0,
        0);
    }
  }
}
