/**
 * Renders shadow effects beneath characters and their projectiles
 * 
 * @param gameSystem Pointer to the game system
 */
void __thiscall renderCharacterShadows(int gameSystem)
{
  int animDataPtr;             // Animation data pointer
  int frameHeight;             // Height of animation frame
  int shadowYOffset;           // Y offset for shadow
  int shadowYPos;              // Y position for shadow
  int shadowYBottom;           // Bottom Y of shadow
  int shadowXPos;              // X position of shadow
  int projectileAnimDataPtr;   // Animation data for projectiles
  int projectileFrameHeight;   // Height of projectile animation frame
  int projectileYOffset;       // Y offset for projectile shadow
  int projectileXPos;          // X position of projectile shadow
  int projectileYPos;          // Y position of projectile shadow
  int projectileYBottom;       // Bottom Y of projectile shadow
  int i;                       // Player index loop counter
  int projectileIndex;         // Current projectile index

  // For each player character
  for (i = 0; i < 2; ++i)
  {
    int playerPtr = *(_DWORD *)(gameSystem + 4 * i + 12);
    
    // Check if player is in valid state for shadow rendering
    if (*(_DWORD *)(playerPtr + 96))
    {
      // Get animation data for current frame
      animDataPtr = *(_DWORD *)(*(_DWORD *)(playerPtr + 16)
                   + 8 * *(unsigned __int16 *)(playerPtr + 8)
                   + 4)
                   + 12 * *(unsigned __int16 *)(playerPtr + 10);
      
      // Calculate frame height and shadow offset
      if (*(__int16 *)(animDataPtr + 6) >= *(__int16 *)(animDataPtr + 10))
      {
        frameHeight = *(__int16 *)(animDataPtr + 10);
        shadowYOffset = *(__int16 *)(animDataPtr + 6) - frameHeight;
      }
      else
      {
        frameHeight = *(__int16 *)(animDataPtr + 6);
        shadowYOffset = 0;
      }
      
      // Calculate shadow Y position (at ground level)
      shadowYPos = shadowYOffset
                + *(_DWORD *)(gameSystem + 1120)
                + 210
                // Adjust for negative Y position (in the air)
                - ((unsigned __int64)*(double *)(playerPtr + 40)
                 - (*(double *)(playerPtr + 40) < 0.0));
      
      // Calculate bottom of shadow
      shadowYBottom = shadowYPos + frameHeight / 3;
      
      // Only render shadow if it's within the visible screen area
      if (shadowYPos < 240 && shadowYBottom > 0)
      {
        // Calculate shadow X position based on player facing direction
        shadowXPos = *(_DWORD *)(gameSystem + 1116)
                  + (unsigned __int64)*(double *)(playerPtr + 32)
                  // Offset based on facing direction
                  - (*(_BYTE *)(playerPtr + 80) == 1) * *(__int16 *)(animDataPtr + 4)
                  - (*(char *)(playerPtr + 80) == -1) 
                  * (*(__int16 *)(animDataPtr + 8) - *(__int16 *)(animDataPtr + 4));
        
        // Render character shadow with semi-transparent effect (color 176)
        blitBackgroundWithColorEffect(
          *(char **)(gameSystem + 32),      // Graphics context
          shadowXPos,                        // Destination X
          shadowYPos,                        // Destination Y
          shadowXPos + *(__int16 *)(animDataPtr + 8), // Destination right
          shadowYBottom,                     // Destination bottom
          *(_DWORD *)(*(_DWORD *)(playerPtr + 20) + 4 * *(unsigned __int16 *)(animDataPtr + 2)), // Image data
          0,                                 // Source X
          0,                                 // Source Y
          *(__int16 *)(animDataPtr + 8),     // Width
          frameHeight,                       // Height
          *(_BYTE *)(playerPtr + 26),        // Transparent color
          *(char *)(playerPtr + 80) == -1,   // Flip horizontally if facing left
          176);                              // Shadow color index
      }
    }
    
    // Get the first projectile index
    projectileIndex = *(__int16 *)(playerPtr + 716);
    
    // Process all active projectiles for this player
    while (projectileIndex != *(__int16 *)(playerPtr + 714))
    {
      // Check if projectile is active and should be rendered
      if (*(_DWORD *)(playerPtr + 4 * projectileIndex + 976) &&
          *(_DWORD *)(playerPtr + 152 * projectileIndex + 1320) &&
          (*(_DWORD *)(playerPtr + 152 * projectileIndex + 1372) || 
           !*(_WORD *)(*(_DWORD *)(gameSystem + 28) + 82446)))
      {
        // Get animation data for projectile
        projectileAnimDataPtr = *(_DWORD *)(*(_DWORD *)(playerPtr + 16)
                              + 8 * *(unsigned __int16 *)(playerPtr + 152 * projectileIndex + 1232)
                              + 4)
                              + 12 * *(unsigned __int16 *)(playerPtr + 152 * projectileIndex + 1234);
        
        // Calculate frame height and shadow offset for projectile
        if (*(__int16 *)(projectileAnimDataPtr + 6) >= *(__int16 *)(projectileAnimDataPtr + 10))
        {
          projectileFrameHeight = *(__int16 *)(projectileAnimDataPtr + 10);
          projectileYOffset = *(__int16 *)(projectileAnimDataPtr + 6) - projectileFrameHeight;
        }
        else
        {
          projectileFrameHeight = *(__int16 *)(projectileAnimDataPtr + 6);
          projectileYOffset = 0;
        }
        
        // Calculate projectile shadow X position based on projectile facing direction
        if (*(char *)(playerPtr + 152 * projectileIndex + 1304) == -1)
        {
          // Facing left
          projectileXPos = *(_DWORD *)(gameSystem + 1116)
                       + (unsigned __int64)*(double *)(playerPtr + 152 * projectileIndex + 1256)
                       - (*(__int16 *)(projectileAnimDataPtr + 8)
                        - *(__int16 *)(projectileAnimDataPtr + 4));
        }
        else
        {
          // Facing right
          projectileXPos = *(_DWORD *)(gameSystem + 1116)
                       + (unsigned __int64)*(double *)(playerPtr + 152 * projectileIndex + 1256)
                       - *(__int16 *)(projectileAnimDataPtr + 4);
        }
        
        // Calculate projectile shadow Y position (at ground level)
        projectileYPos = projectileYOffset
                      + *(_DWORD *)(gameSystem + 1120)
                      + 210
                      - (unsigned __int64)*(double *)(playerPtr + 152 * projectileIndex + 1264);
        
        // Calculate bottom of projectile shadow
        projectileYBottom = projectileYPos + projectileFrameHeight / 3;
        
        // Only render shadow if it's within the visible screen area
        if (projectileYPos < 240 && projectileYBottom > 0)
        {
          // Render projectile shadow with semi-transparent effect (color 176)
          blitBackgroundWithColorEffect(
            *(char **)(gameSystem + 32),      // Graphics context
            projectileXPos,                    // Destination X
            projectileYPos,                    // Destination Y
            projectileXPos + *(__int16 *)(projectileAnimDataPtr + 8), // Destination right
            projectileYBottom,                 // Destination bottom
            *(_DWORD *)(*(_DWORD *)(playerPtr + 20) + 4 * *(unsigned __int16 *)(projectileAnimDataPtr + 2)), // Image data
            0,                                 // Source X
            0,                                 // Source Y
            *(__int16 *)(projectileAnimDataPtr + 8), // Width
            projectileFrameHeight,             // Height
            *(_BYTE *)(playerPtr + 26),        // Transparent color
            *(char *)(playerPtr + 152 * projectileIndex + 1304) == -1, // Flip horizontally if facing left
            176);                              // Shadow color index
        }
      }
      
      // Move to next projectile index (circular buffer with 64 slots)
      if (++projectileIndex >= 64)
        projectileIndex = 0;
    }
  }
}
