/**
 * Renders black borders when the camera view extends beyond the playfield edges
 * 
 * @param gameSystem Pointer to the game system
 * @return TRUE if screen was successfully presented
 */
BOOL __thiscall renderScreenBoundaries(int *gameSystem)
{
  int cameraOffsetX;          // Camera X offset to apply
  int cameraOffsetY;          // Camera Y offset to apply
  int horizontalClipOffset;   // Amount to clip on X axis
  int verticalClipOffset;     // Amount to clip on Y axis
  int *rectPtr;               // Rectangle helper pointer
  
  // Rectangle storage for filling operations
  _DWORD verticalBorderRect[4];  // Rectangle for top/bottom borders
  int vbLeft;                 // Left coordinate
  int vbTop;                  // Top coordinate
  int vbRight;                // Right coordinate 
  int vbBottom;               // Bottom coordinate
  
  _DWORD horizontalBorderRect[4]; // Rectangle for left/right borders
  int hbLeft;                 // Left coordinate
  int hbTop;                  // Top coordinate
  int hbRight;                // Right coordinate 
  int hbBottom;               // Bottom coordinate
  
  // Calculate camera offset from the center of screen
  cameraOffsetX = -gameSystem[279];  // Camera X position
  cameraOffsetY = 240 - gameSystem[280];  // Camera Y position (240 is screen height)
  
  // Initialize clipping variables
  horizontalClipOffset = 0;
  verticalClipOffset = 0;
  
  // Handle horizontal (X-axis) boundaries
  if (cameraOffsetX <= 320)  // 320 is screen width
  {
    if (cameraOffsetX < 0)
    {
      // Camera has gone too far left, clip the view
      horizontalClipOffset = -cameraOffsetX;
      cameraOffsetX = 0;
    }
  }
  else
  {
    // Camera has gone too far right, clip the view
    horizontalClipOffset = 320 - cameraOffsetX;
    cameraOffsetX = 320;
  }
  
  // Handle vertical (Y-axis) boundaries
  if (cameraOffsetY <= 240)  // 240 is screen height
  {
    if (cameraOffsetY < 0)
    {
      // Camera has gone too far up, clip the view
      verticalClipOffset = -cameraOffsetY;
      cameraOffsetY = 0;
    }
  }
  else
  {
    // Camera has gone too far down, clip the view
    verticalClipOffset = 240 - cameraOffsetY;
    cameraOffsetY = 240;
  }
  
  // Draw vertical borders (top or bottom black bars)
  int absVerticalClip = abs(verticalClipOffset);
  rectPtr = setRectFromCoordinates(
    verticalBorderRect, 
    0,                                // Left at screen edge
    (verticalClipOffset < 0) * (verticalClipOffset + 240),  // Top position (0 or calculated)
    320,                              // Fill entire width
    absVerticalClip                   // Height of the border
  );
  vbLeft = *rectPtr;
  vbTop = rectPtr[1];
  vbRight = rectPtr[2];
  vbBottom = rectPtr[3];
  
  // Fill vertical borders with black color (0)
  fillRectangleWithColor((_DWORD **)gameSystem[8], vbLeft, vbTop, vbRight, vbBottom, 0);
  
  // Draw horizontal borders (left or right black bars)
  int absHorizontalClip = abs(horizontalClipOffset);
  int visibleHeight = 240 - absVerticalClip;  // Height of screen minus vertical borders
  
  rectPtr = setRectFromCoordinates(
    horizontalBorderRect, 
    (horizontalClipOffset < 0) * (horizontalClipOffset + 320),  // Left position (0 or calculated)
    verticalClipOffset * (verticalClipOffset >= 0),      // Top position (after vertical border)
    absHorizontalClip,                                   // Width of the border
    visibleHeight                                       // Height of visible area
  );
  hbLeft = *rectPtr;
  hbTop = rectPtr[1];
  hbRight = rectPtr[2];
  hbBottom = rectPtr[3];
  
  // Fill horizontal borders with black color (0)
  fillRectangleWithColor((_DWORD **)gameSystem[8], hbLeft, hbTop, hbRight, hbBottom, 0);
  
  // Present the final screen
  return presentFrameToScreen(gameSystem[8]);
}

