#define SYS_DUMMY_BLOCK           4936 // boolean toggle (Practice; F7)
#define SYS_FLAG_4944             4944 // gating flag for F4 path
#define SYS_FLAG_4948             4948 // gating flag (dword) for F4 path
#define SYS_MODE                  4964 // 1=Practice, 5=Replay, 6=special (pre-fight/attract), etc.
#define SYS_REPLAY_IO_MODE        82563// 1=read, 2=write
#define SYS_REPLAY_HANDLE         82564// file handle pointer for IO

