    int p1 = *(_DWORD *)(battleContext + BC_OFFSET_P1_PTR);
    int p2 = *(_DWORD *)(battleContext + BC_OFFSET_P2_PTR);
    *(_WORD *)(p1 + PLAYER_PARAM_A) = *(_WORD *)(battleContext + BC_OFFSET_PARAM_A);
    *(_WORD *)(p2 + PLAYER_PARAM_A) = *(_WORD *)(battleContext + BC_OFFSET_PARAM_A);
