  int *rectCoordinates;                // Rectangle bounds
  double finalDamage;                  // Calculated final damage value
  double damageWithRF;                 // Damage with RF meter multiplier
  double baseDamage;                   // Base damage value from move data
  _DWORD hitboxTemp1[4];               // Temporary storage for hitbox 1
  _DWORD hitboxTemp2[4];               // Temporary storage for hitbox 2
  int rectLeft;                        // Left bound of collision rectangle
  int rectTop;                         // Top bound of collision rectangle
  int rectRight;                       // Right bound of collision rectangle
  int rectBottom;                      // Bottom bound of collision rectangle
  _DWORD collisionRectangle[4];        // Calculated collision rectangle bounds
  int boundsLeft;                      // Collision bounds left
  int boundsTop;                       // Collision bounds top
  int boundsRight;                     // Collision bounds right
  int boundsBottom;                    // Collision bounds bottom
  int collisionFlag;                   // If any collision occurred
