  // Get the current move data for both entities
  attackerMoveData = *(_DWORD *)(*(_DWORD *)(attackerPtr + 356) + 8 * *attackerEntity + 4) + 
                     200 * *(unsigned __int16 *)(attackerPtr + 152 * attackerIdx + 1234);
  defenderMoveData = (int *)(*(_DWORD *)(*(_DWORD *)(defenderPtr + 356) + 8 * *defenderEntity + 4) + 
                      200 * *(unsigned __int16 *)(defenderPtr + 152 * defenderIdx + 1234));
  
