//----- (00774A10) --------------------------------------------------------
// Original name: sub_774A10
/**
 * Renders a number as individual digits on screen, drawing from right to left
 * 
 * @param screenContext Pointer to screen context
 * @param xPos Starting X position for rightmost digit
 * @param yPos Y position for the digits
 * @param number The number to render
 * @return The quotient after dividing by 10 repeatedly (always 0)
 */
unsigned int __thiscall renderDigits(int screenContext, int xPos, int yPos, unsigned int number)
{
  unsigned int remainingValue; // Current value to render
  
  // Process each digit from right to left (ones, tens, hundreds...)
  remainingValue = number;
  do
  {
    // Render the current rightmost digit
    // Each digit is stored in a sprite sheet with 10 digits (0-9),
    // where each digit is 16x19 pixels, starting at y=455
    blitSurfaceWithTransparency(
      *(_DWORD ***)(screenContext + 32),  // Graphics context
      xPos - 16,                          // Left position
      yPos,                               // Top position
      xPos,                               // Right position
      yPos + 19,                          // Bottom position
      *(_DWORD *)(screenContext + 1080),  // Digit surface
      16 * (remainingValue % 10),         // Source X (digit * width)
      455,                                // Source Y
      16 * (remainingValue % 10 + 1),     // Source right
      474,                                // Source bottom
      *(_BYTE *)(*(_DWORD *)(screenContext + 28) + 3892), // Transparent color
      0                                   // No horizontal flip
    );
    
    // Move to the left for the next digit
    xPos -= 14;  // Note: 14 pixels spacing between digits (not 16)
    
    // Get the next digit
    remainingValue /= 10;
  }
  while (remainingValue > 0);
  
  return remainingValue; // Always 0 when exiting the loop
}

