/**
 * Wrapper function that converts integer power calculation to double
 * 
 * @param base The base value
 * @param exponent The exponent value
 * @return base^exponent as a double
 */
double __cdecl getIntegerPowerAsFloat(int base, int exponent)
{
  return (double)calculateIntegerPower(base, exponent);
}

//----- (00775830) --------------------------------------------------------
//----- (00775830) --------------------------------------------------------
// Original name: sub_775830
/**
 * Calculates an integer raised to an integer power (base^exponent)
 * Handles negative exponents by returning 1/result
 * 
 * @param base The base value
 * @param exponent The exponent value
 * @return base^exponent as an integer
 */
int __cdecl calculateIntegerPower(int base, int exponent)
{
  int result;           // Final result 
  unsigned int absExp;  // Absolute value of exponent
  
  // Convert negative exponent to positive for calculation
  if (exponent < 0)
    absExp = -exponent;
  else
    absExp = exponent;
  
  // Initialize result
  result = 1;
  
  // Fast binary exponentiation algorithm
  while (1)
  {
    // If current bit of exponent is 1, multiply result by current base
    if ((absExp & 1) != 0)
      result *= base;
    
    // Shift exponent right by 1 bit (divide by 2)
    absExp >>= 1;
    
    // If no more bits in exponent, we're done
    if (!absExp)
      break;
    
    // Square the base for next iteration
    base *= base;
  }
  
  // Return result or its reciprocal for negative exponents
  if (exponent >= 0)
    return result;
  else
    return 1 / result; // Note: integer division, so this will be 0 for results < 1
}

