/**
 * Renders the title/main menu screen.
 * 
 * This function renders the title screen background, which may be scrolling based on
 * the vertical position stored in the screen context. If the vertical position exceeds
 * 2280 pixels, it renders the image from its maximum scroll position.
 * 
 * @param screenContext Pointer to the screen context
 * @return Result from presenting the rendered frame
 */
BOOL __thiscall renderTitleScreen(int screenContext)
{
  int *rectPtr; // eax
  
  // Rectangle definitions for source and destination areas
  _DWORD sourceRect[4]; // [esp+4h] [ebp-80h] BYREF
  int sourceX; // [esp+14h] [ebp-70h]
  int sourceY; // [esp+18h] [ebp-6Ch]
  int sourceWidth; // [esp+1Ch] [ebp-68h]
  int sourceHeight; // [esp+20h] [ebp-64h]
  
  _DWORD destRect[4]; // [esp+24h] [ebp-60h] BYREF
  int destX; // [esp+34h] [ebp-50h]
  int destY; // [esp+38h] [ebp-4Ch]
  int destWidth; // [esp+3Ch] [ebp-48h]
  int destHeight; // [esp+40h] [ebp-44h]
  
  _DWORD altSourceRect[4]; // [esp+44h] [ebp-40h] BYREF
  int altSourceX; // [esp+54h] [ebp-30h]
  int altSourceY; // [esp+58h] [ebp-2Ch]
  int altSourceWidth; // [esp+5Ch] [ebp-28h]
  int altSourceHeight; // [esp+60h] [ebp-24h]
  
  _DWORD altDestRect[4]; // [esp+64h] [ebp-20h] BYREF
  int altDestX; // [esp+74h] [ebp-10h]
  int altDestY; // [esp+78h] [ebp-Ch]
  int altDestWidth; // [esp+7Ch] [ebp-8h]
  int altDestHeight; // [esp+80h] [ebp-4h]

  // Check if the title screen is within the normal scroll range
  if (*(double *)(screenContext + 1080) <= 2280.0)
  {
    // Set up destination rectangle for normal scroll position
    rectPtr = setRectFromCoordinates(destRect, 0, (unsigned __int64)*(double *)(screenContext + 1080), 320, 240);
    destX = *rectPtr;
    destY = rectPtr[1];
    destWidth = rectPtr[2];
    destHeight = rectPtr[3];
    
    // Set up source rectangle for the entire screen
    rectPtr = setRectFromCoordinates(sourceRect, 0, 0, 320, 240);
    sourceX = *rectPtr;
    sourceY = rectPtr[1];
    sourceWidth = rectPtr[2];
    sourceHeight = rectPtr[3];
    
    // Copy the title screen image with transparency
    blitSurfaceWithTransparency(
        *(_DWORD ***)(screenContext + 32),  // Graphics context
        sourceX, sourceY,                    // Source position
        sourceWidth, sourceHeight,           // Source dimensions
        *(_DWORD *)(screenContext + 1076),   // Source surface
        destX, destY,                        // Destination position
        destWidth, destHeight,               // Destination dimensions
        0,                                   // Transparent color (0 = none)
        0                                    // No horizontal flip
    );
  }
  else
  {
    // Set up destination rectangle for maximum scroll position
    rectPtr = setRectFromCoordinates(altDestRect, 0, 2280, 320, 240);
    altDestX = *rectPtr;
    altDestY = rectPtr[1];
    altDestWidth = rectPtr[2];
    altDestHeight = rectPtr[3];
    
    // Set up source rectangle for the entire screen
    rectPtr = setRectFromCoordinates(altSourceRect, 0, 0, 320, 240);
    altSourceX = *rectPtr;
    altSourceY = rectPtr[1];
    altSourceWidth = rectPtr[2];
    altSourceHeight = rectPtr[3];
    
    // Copy the title screen image with transparency from max scroll position
    blitSurfaceWithTransparency(
        *(_DWORD ***)(screenContext + 32),    // Graphics context
        altSourceX, altSourceY,               // Source position
        altSourceWidth, altSourceHeight,      // Source dimensions
        *(_DWORD *)(screenContext + 1076),    // Source surface
        altDestX, altDestY,                   // Destination position
        altDestWidth, altDestHeight,          // Destination dimensions
        0,                                    // Transparent color (0 = none)
        0                                     // No horizontal flip
    );
  }
  
  // Present the rendered frame to the screen
  return presentFrameToScreen(*(_DWORD *)(screenContext + 32));
}
